#!/usr/bin/env python3
import csv
import gzip
import itertools
import math
import sys


def open_text(path):
    with open(path, "rb") as handle:
        magic = handle.read(2)
    if magic == b"\x1f\x8b":
        return gzip.open(path, "rt")
    return open(path, "rt")


def parse_matrix(path):
    rows = {}
    with open_text(path) as handle:
        reader = csv.reader(handle, delimiter="\t")
        header = next(reader)
        if len(header) != 9:
            raise ValueError("expected one feature column and eight populations")
        for fields in reader:
            if len(fields) != 9:
                continue
            rows[fields[0]] = [float(x) for x in fields[1:]]
    return header[1:], rows


